examples.template:
CompositionLocalProvider(LocalConfiguration provides locale) {
    Column {
        @OptIn(ExperimentalMonarchApi::class)
        MonarchAiThread(
            messages = listOf(
                MonarchAiConversationMessage(
                    id = {{messages.0.id}},
                    role = MonarchAiRole.{{messages.0.role|pascal}},
                    parts = listOf(MonarchAiTextPart({{messages.0.text}})),
                    createdAt = {{messages.0.createdAt}},
                ),
                MonarchAiConversationMessage(
                    id = {{messages.1.id}},
                    role = MonarchAiRole.{{messages.1.role|pascal}},
                    parts = listOf(MonarchAiTextPart({{messages.1.text}})),
                    createdAt = {{messages.1.createdAt}},
                    agent = MonarchAiAgentRef(name = {{messages.1.agent.name}}, role = {{messages.1.agent.role}}),
                ),
            ),
            modifier = Modifier.height(MonarchTheme.spacing.space24 * 4),
            timeZone = {{timeZone}},
            nowMillis = {{now|millis}},
        )
        MonarchAiPromptInput(
            label = "Send a message",
            state = prompt,
            onSubmit = {},
            busy = true,
            onStop = {},
        )
    }
}

