examples.setup:
val messages = remember {
    List(6) { i ->
        MonarchAiConversationMessage(
            id = "m$i",
            role = if (i % 2 == 0) MonarchAiRole.User else MonarchAiRole.Assistant,
            parts = listOf(MonarchAiTextPart("Message ${i + 1}")),
            createdAt = "2026-11-05T09:0$i:00.000Z",
        )
    }
}
var loading by remember { mutableStateOf(false) }
